 if(!verifyCsrfToken($_POST['csrf_token']??null))$errors[]='Your session expired. Please try again.';
 elseif(!$pdo)$errors[]='The database is temporarily unavailable.';
 else{try{$id=filter_input(INPUT_POST,'withdrawal_id',FILTER_VALIDATE_INT)?:0;$decision=(string)($_POST['decision']??'');$changed=reviewPhysicianWithdrawal($pdo,$id,(int)$user['UserID'],$decision);if($changed)logActivity($pdo,(int)$user['UserID'],null,$decision==='pay'?'Simulated physician payout':'Rejected demo withdrawal','Withdrawal #'.$id.'; no real transfer.');$_SESSION['withdrawal_review_success']=$changed?($decision==='pay'?'Payout simulated. No money was transferred.':'Withdrawal rejected. Reserved earnings are available again.'):'This request has already been reviewed.';header('Location: '.HQ_BASE_URL.'/admin/physician-withdrawals.php',true,303);exit;}catch(PDOException $e){error_log('Withdrawal review failed: '.$e->getMessage());$errors[]='We could not review this request. Please try again.';}catch(RuntimeException $e){$errors[]=$e->getMessage();}}
