<?php foreach(['Reference'=>$row['Reference'],'Physician'=>'Dr. '.$row['FirstName'].' '.$row['LastName'],'Amount'=>'PHP '.number_format((float)$row['Amount'],2),'Method'=>$row['PayoutMethod'],'Account holder'=>$row['AccountName'],'Destination'=>$row['BankName']?:$row['PayoutMethod'],'Account number'=>$row['AccountNumber'],'Status'=>withdrawalStatus($row['Status']),'Requested'=>$row['CreatedAt'],'Reviewed'=>$row['ReviewedAt']?:'Not yet reviewed'] as $label=>$value): ?><div><dt><?= $label ?></dt><dd><?= htmlspecialchars($value) ?></dd></div><?php endforeach; ?></dl>
